// functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.
//
// Steps (e2e):
//   Then the table shows {n} rows
//   Then row {n} shows {text}
//   When I sort by {column}
//   Then the column {column} is sorted {direction}
//   When I select the row {name}
//   Then the row {name} is selected
//   When I select all rows on this page
//   When I open the actions for {name}
//   When I go to page {n}
//   When I go to the next page
//   When I go to the previous page
//   Then page {n} is the current page
//   Then the table is in the {state} state
// States (from the card): Default, Sorted, Row selected, All selected, Loading a page, Empty, Error, First / last
// page, Many pages, Rows selected. Checked by the state step: Default, Row selected, Loading a page, Empty.
import { Registry } from '../../js/registry.js';
import * as p from '../../js/primitives.js';

export const BLOCK = 'DataTable';
export const ROUTE = '/words?sort=added&dir=desc&page=1';
export const STATES = ["Default", "Sorted", "Row selected", "All selected", "Loading a page", "Empty", "Error", "First / last page", "Many pages", "Rows selected"];
export const DEFAULT_STATE = 'Default';
export const CHECKED_STATES = ["Default", "Row selected", "Loading a page", "Empty"];
export const DEMO = ["kit/blocks/data/DataTable.html"];
export const SELF_TEST = [
  "Then the table shows 2 rows",
  "Then row 1 shows \"駅\"",
  "Then row 2 shows \"train\"",
  "Then the column \"Added\" is sorted descending",
  "Then the table is in the \"Default\" state",
  "When I select the row \"駅\"",
  "Then the row \"駅\" is selected",
  "Then page 1 is the current page",
  "When I go to page 2",
  "Then the table shows 2 rows",
];

export const steps = new Registry({ block: BLOCK });

/** The DataTable block on a page: its controls, found as a person finds them (role and name, label, text). */
export class DataTable {
  constructor(page, baseURL = '') {
    this.page = page;
    this.baseURL = baseURL;
  }

  async form() {
    return p.control(this.page, { css: 'form:has(table)', block: BLOCK });
  }

  async table() {
    return p.control(this.page, { role: 'table', block: BLOCK });
  }

  /** Every match, possibly none (for counting). */
  async tableAll() {
    return this.page.getByRole('table');
  }

  async rows() {
    return p.control(await this.table(), { css: 'tbody tr', block: BLOCK });
  }

  /** Every match, possibly none (for counting). */
  async rowsAll() {
    return (await this.table()).locator('tbody tr');
  }

  async row(n) {
    return (await p.control(await this.table(), { css: 'tbody tr', block: BLOCK })).nth(Number(n) - 1);
  }

  async selectedRow() {
    return p.control(await this.table(), { css: 'tbody tr[data-state="selected"]', block: BLOCK });
  }

  async column(column) {
    return p.control(await this.table(), { role: 'columnheader', name: String(column), block: BLOCK });
  }

  async sort(column) {
    return p.control(await this.table(), { role: 'button', name: `Sort by ${column}`, block: BLOCK });
  }

  async selectAll() {
    return p.control(await this.table(), { role: 'checkbox', name: 'Select all on this page', block: BLOCK });
  }

  async selectRow(name) {
    return p.control(await this.table(), { role: 'checkbox', name: `Select ${name}`, exact: true, block: BLOCK });
  }

  async rowActions(name) {
    return p.control(await this.table(), { role: 'link', name: `Actions for ${name}`, exact: true, block: BLOCK });
  }

  async pages() {
    return p.control(this.page, { role: 'navigation', name: 'Pages', block: BLOCK });
  }

  async pageLink(n) {
    return p.control(await this.pages(), { role: 'link', name: `Page ${n}`, exact: true, block: BLOCK });
  }

  async previous() {
    return p.control(await this.pages(), { role: 'link', name: 'Previous', block: BLOCK });
  }

  async next() {
    return p.control(await this.pages(), { role: 'link', name: 'Next', block: BLOCK });
  }

  /** Check one of the card's states: Default, Row selected, Loading a page, Empty. */
  async expectState(state) {
    const b = this;
    if (state === 'Default') {
      await p.expectVisible((await b.rows()).first());
    } else if (state === 'Row selected') {
      await p.expectVisible((await b.selectedRow()).first());
    } else if (state === 'Loading a page') {
      await p.expectAttribute(await b.form(), 'aria-busy', 'true');
    } else if (state === 'Empty') {
      await p.expectCount(await b.tableAll(), 0);
    } else {
      throw new Error(`DataTable has no check for the state '${state}'; checked: ${CHECKED_STATES.join(', ')}`);
    }
  }
}

steps.step("Then the table shows {n} rows", async (world, { n }) => {
  const b = new DataTable(world.page, world.baseURL ?? '');
  await p.expectCount(await b.rowsAll(), Number(n));
}, { level: 'e2e' });

steps.step("Then row {n} shows {text}", async (world, { n, text }) => {
  const b = new DataTable(world.page, world.baseURL ?? '');
  await p.expectText(await b.row(n), String(text));
}, { level: 'e2e' });

